def is_power_of_five(N):
    """Checks if N is a power of 5."""
    if N <= 0:
        return False
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

solutions = []
for n in range(3, 31):
    if n % 4 == 3:
        X = (2**n) - 3
        if is_power_of_five(X):
            solutions.append(n)
            print(f"n = {n}: 2^{n} - 3 = {X} = 5^k (Solution found)")
        # else:
        #     print(f"n = {n}: 2^{n} - 3 = {X} (Not a solution)")

print("\n--- Summary ---")
print(f"Found solutions for n: {solutions}")

